  const cnt269of = d => { const s = ST.statSlice({obj:'obj-measure', dims:[], inds:['a-count'], date: d});
    return (s.ok ? s.total['a-count'].v : 'отказ') + '/' + new Set(ST.measureAt(d).map(r => r.ref)).size; };
  const rowsOf269 = ref => ST.state.rows.filter(r => r.obj === 'obj-measure' && r.ref === ref)
